function extractEmbedded(name) {
  const prefix = `const ${name} = `;
  const start = src.indexOf(prefix);
  if (start < 0) throw new Error(`TornPulse slick HUD: could not find ${name}`);
  const valueStart = start + prefix.length;
  if (src[valueStart] !== '"') throw new Error(`TornPulse slick HUD: ${name} is not a JSON string`);
  let i = valueStart + 1;
  let escaped = false;
  for (; i < src.length; i++) {
    const ch = src[i];
    if (escaped) { escaped = false; continue; }
    if (ch === '\\') { escaped = true; continue; }
    if (ch === '"') break;
  }
  if (i >= src.length || src[i + 1] !== ';') throw new Error(`TornPulse slick HUD: could not parse ${name}`);
  return { start: valueStart, end: i + 1, value: JSON.parse(src.slice(valueStart, i + 1)) };
}

function setEmbedded(name, value) {
  const found = extractEmbedded(name);
  src = src.slice(0, found.start) + JSON.stringify(value) + src.slice(found.end);
}

function replaceExact(text, oldText, newText, label) {
  const count = text.split(oldText).length - 1;
  if (count !== 1) throw new Error(`TornPulse slick HUD: expected 1 match for ${label}, found ${count}`);
  console.log(`✓ ${label}`);
  return text.replace(oldText, newText);
}

function replaceKotlinFunction(text, signature, replacement, label) {
  const start = text.indexOf(signature);
  if (start < 0) throw new Error(`TornPulse slick HUD: ${label} function not found`);
  const open = text.indexOf('{', start);
  if (open < 0) throw new Error(`TornPulse slick HUD: ${label} opening brace not found`);
  let depth = 1;
  let end = -1;
  for (let i = open + 1; i < text.length; i++) {
    const ch = text[i];
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) { end = i + 1; break; }
    }
  }
  if (end < 0) throw new Error(`TornPulse slick HUD: ${label} closing brace not found`);
  console.log(`✓ ${label}`);
  return text.slice(0, start) + replacement + text.slice(end);
}

function replaceAfterMarker(text, marker, oldText, newText, label) {
  const at = text.indexOf(marker);
  if (at < 0) throw new Error(`TornPulse slick HUD: ${label} marker not found`);
  const hit = text.indexOf(oldText, at);
  if (hit < 0) throw new Error(`TornPulse slick HUD: ${label} target not found`);
  console.log(`✓ ${label}`);
  return text.slice(0, hit) + newText + text.slice(hit + oldText.length);
}

