function replaceOptionalExact(text, oldText, newText, label) {
  const count = text.split(oldText).length - 1;
  if (count === 1) {
    console.log(`✓ ${label}`);
    return text.replace(oldText, newText);
  }
  console.log(`- ${label} skipped`);
  return text;
}

function replaceRegexOne(text, regex, replacer, label) {
  let hits = 0;
  const out = text.replace(regex, (...args) => { hits++; return typeof replacer === 'function' ? replacer(...args) : replacer; });
  if (hits === 1) {
    console.log(`✓ ${label}`);
    return out;
  }
  if (hits === 0) {
    console.log(`- ${label} skipped`);
    return text;
  }
  throw new Error(`TornPulse brand cleanup: expected 1 match for ${label}, found ${hits}`);
}

function writeBase64Asset(fileName, b64) {
  fs.writeFileSync(path.join(process.cwd(), fileName), Buffer.from(b64, 'base64'));
  console.log(`✓ wrote ${fileName}`);
}

